def choose_move(observation):
    pos = observation.get("self_position", {}) if isinstance(observation.get("self_position", {}), dict) else {}
    x = pos.get("x", 0)
    y = pos.get("y", 0)

    grid_w = observation.get("grid_width", 0)
    grid_h = observation.get("grid_height", 0)

    resources = observation.get("resources", [])
    obstacles = observation.get("obstacles", [])
    opponent = observation.get("opponent_position", {})
    ox = opponent.get("x", 0)
    oy = opponent.get("y", 0)

    # Helper to clamp moves
    def clamp(dx, dy):
        if dx not in (-1, 0, 1) or dy not in (-1, 0, 1):
            return 0, 0
        return dx, dy

    # 1) Move toward nearest resource if present
    best_dx = 0
    best_dy = 0
    min_dist = float("inf")
    if isinstance(resources, list):
        for r in resources:
            rx = r.get("x", 0)
            ry = r.get("y", 0)
            dist = abs(rx - x) + abs(ry - y)
            if dist < min_dist:
                min_dist = dist
                best_dx = 1 if rx > x else -1 if rx < x else 0
                best_dy = 1 if ry > y else -1 if ry < y else 0
    if min_dist < float("inf"):
        return [best_dx, best_dy]

    # 2) Flee from opponent if close
    if isinstance(opponent, dict):
        odx = 0
        ody = 0
        if ox is not None and oy is not None:
            dist_to_op = abs(ox - x) + abs(oy - y)
            if dist_to_op <= 2:
                odx = -1 if ox > x else 1 if ox < x else 0
                ody = -1 if oy > y else 1 if oy < y else 0
                return clamp(odx, ody)

    # 3) Blocked or no info: try a neutral move avoiding obstacles
    move_candidates = [(-1, 0), (1, 0), (0, -1), (0, 1), (0, 0)]
    def is_block(nx, ny):
        if grid_w and (nx < 0 or nx >= grid_w):
            return True
        if grid_h and (ny < 0 or ny >= grid_h):
            return True
        if isinstance(obstacles, list):
            for o in obstacles:
                ox2 = o.get("x", 0)
                oy2 = o.get("y", 0)
                if nx == ox2 and ny == oy2:
                    return True
        return False
    for dx, dy in move_candidates:
        nx = x + dx
        ny = y + dy
        if is_block(nx, ny):
            continue
        return [dx, dy]

    return [0, 0]
